import sys
import os
import subprocess
import re

def read_template(template_path):
    with open(template_path, 'r') as f:
        return f.read()

def process_input(template_content):
    results = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            process = subprocess.Popen(line, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            stdout, stderr = process.communicate()
            results.append({
                'command': line,
                'stdout': stdout,
                'stderr': stderr,
                'exit_code': process.returncode
            })
        except Exception as e:
            results.append({
                'command': line,
                'stdout': '',
                'stderr': str(e),
                'exit_code': -1
            })
    return results

def generate_html(template_content, results):
    if '<!--RESULTS-->' not in template_content:
        return template_content

    result_html = []
    for result in results:
        section = f"""
<section>
<h2>{result['command']}</h2>
<pre>{result['stdout']}</pre>
<pre>{result['stderr']}</pre>
<p>Exit status: {result['exit_code']}</p>
</section>
"""
        result_html.append(section)

    return template_content.replace('<!--RESULTS-->', '\n'.join(result_html))

def main():
    template_path = sys.argv[1] if len(sys.argv) > 1 else 'report_template.html'
    template_content = read_template(template_path)
    results = process_input(template_content)
    output_html = generate_html(template_content, results)
    with open('build-report.html', 'w') as f:
        f.write(output_html)

if __name__ == '__main__':
    main()
